import React, { useState } from 'react';
import { ToggleButton } from 'primereact/togglebutton';

export default function Customized() {
    const [checked, setChecked] = useState(false);

    return (
        <ToggleButton 
            onLabel="I confirm" 
            offLabel="I reject" 
            onIcon="pi pi-check" 
            offIcon="pi pi-times" 
            checked={checked} onChange={(e) => setChecked(e.value)} 
            className="w-150" />
    );
}